"""§wyrl§ Engine v7.9: promote the editor-authored Sanctuary & Makers Grotto as the canonical Dragon Den."""
import base64,gzip,json
PAYLOAD_B64=""
def _once(s,a,b):
    if a not in s: raise RuntimeError("v7.9 token missing: "+a[:180])
    return s.replace(a,b,1)
def apply(html):
    s=html
    for a,b in {
      "V7_8_LAYERS_DESKTOP_DOCKS":"V7_9_SANCTUARY_CANONICAL_PROJECT",
      "Maker v7.8":"Maker v7.9","MAKER v7.8":"MAKER v7.9",
      "v7.8 · LAYERS + DESKTOP DOCKS":"v7.9 · SANCTUARY CANONICAL PROJECT",
      "version:'v7.8'":"version:'v7.9'",
      "version:'swyrl-engine-agent-v5.8'":"version:'swyrl-engine-agent-v5.9'",
      "engine:'§wyrl§ Engine · Maker v7.8'":"engine:'§wyrl§ Engine · Maker v7.9'",
      "version:7.8":"version:7.9",
    }.items(): s=_once(s,a,b)
    data=json.loads(gzip.decompress(base64.b64decode(PAYLOAD_B64)).decode())
    assert len(data["scene"]["actors"])==120 and data["editor"]["revision"]==14
    data["engine"]="§wyrl§ Engine · Maker v7.9";data["version"]=7.9
    data["project"].update({"name":"Glitch Dragon Den — Sanctuary & Makers Grotto","template":"glitch-dragons-den","kind":"dragons-den","environment":"dragon-den","canonicalId":"dragon-den"})
    # Project-owned scripting namespace: empty today, but ownership travels with this project and never becomes engine-global.
    data["project"].setdefault("scripts",{"schema":"swyrl-project-scripts-v1","text":[],"graphs":[],"packages":[]})
    canonical=json.dumps(data,separators=(",",":"),ensure_ascii=False).replace("</","<\\/")
    a="const CANONICAL_GLITCH_DEN_PROJECT=";i=s.index(a);j=s.index(";\nfunction loadCanonicalGlitchDen",i)
    s=s[:i]+a+canonical+s[j:]
    s=s.replace("Glitch Dragon Den — Moonfire Sanctum","Glitch Dragon Den — Sanctuary & Makers Grotto")
    s=s.replace("The authored 120-actor Dragon Glitch Den, promoted directly from the saved §E project.","The editor-authored 120-actor Sanctuary & Makers Grotto, promoted directly from the saved §E project.")
    s=s.replace("Open Moonfire Sanctum","Open Sanctuary & Makers Grotto")
    s=s.replace("authored revision 142 · 120 actors","authored Sanctuary revision 14 · 120 actors")
    s=s.replace("Glitch Dragon Den · Moonfire Sanctum","Glitch Dragon Den · Sanctuary & Makers Grotto")
    s=s.replace("canonicalStarter:'moonfire-sanctum-r142'","canonicalStarter:'sanctuary-makers-grotto-r14'")
    s=s.replace("editorLog('§wyrl§ Engine v7.8 initialized · multi-object layers · collapsible desktop docks','ok')","editorLog('§wyrl§ Engine v7.9 initialized · Sanctuary & Makers Grotto canonical Dragon Den','ok')")
    return s
